import { SourceTypes } from "../types/sourceTypes";
import type { AssetName } from "./assetLoaders";

// How SocialIcons draws the network: exactly one of the two.
type NetworkIcon =
  // Iconify icon name (simple-icons:<slug>, mdi:<icon>…), drawn in `color`
  | { icon: string; logo?: never }
  // local logo from src/assets/social-icons, loaded on demand (see LocalIcon.tsx)
  | { logo: AssetName; icon?: never };

type socialNetworkType = Record<
  string,
  NetworkIcon & {
    color: string;
    name?: string;
    category:
      | "social"
      | "messaging_app"
      | "video_platform"
      | "adult"
      | "streaming"
      | "gaming"
      | "sport"
      | "ecommerce"
      | "finance"
      | "dating"
      | "other"
      | "programming"
      | "hacking"
      | "bot"
      | "search_engine"
      | "images-search-engine"
      | "paste";
  }
>;

